import qsharp
from collections import Counter

qsharp.init(target_profile=qsharp.TargetProfile.Base)

qsharp_code = r"""
operation MarkedStateOracle(qs : Qubit[]) : Unit {
    // Phase flip the marked state |1110> (q[0]=0, q[1..3]=1)
    // Apply X to qubit 0 to turn |1110> into |1111>, then controlled Z, then undo X
    X(qs[0]);
    Controlled Z([qs[1], qs[2], qs[3]], qs[0]);
    X(qs[0]);
}

operation Diffusion(qs : Qubit[]) : Unit {
    ApplyToEach(H, qs);
    ApplyToEach(X, qs);
    Controlled Z([qs[1], qs[2], qs[3]], qs[0]);
    ApplyToEach(X, qs);
    ApplyToEach(H, qs);
}

operation GroverSearch() : Result[] {
    use qs = Qubit[4];
    ApplyToEach(H, qs);
    MarkedStateOracle(qs);
    Diffusion(qs);
    mutable result = [One, One, One, One];
    for i in 0..3 {
        set result w/= i <- M(qs[i]);
    }
    ResetAll(qs);
    return result;
}
"""

qsharp.eval(qsharp_code)

shots = 500
results = list(qsharp.run("GroverSearch()", shots=shots))

# The marked state |1110> in Q# little-endian is [Zero, One, One, One]
success = 0
for r in results:
    if list(r) == [0, 1, 1, 1]:
        success += 1

print(f"Total shots: {shots}")
print(f"Success count (measured 1110): {success}")
print(f"Success rate: {success / shots * 100:.2f}%")

# Also print the full distribution
counts = Counter(tuple(r) for r in results)
print("\nTop outcomes:")
for outcome, count in counts.most_common(5):
    print(f"  {outcome}: {count}")

import numpy as np
import pennylane as qml
from pennylane.optimize import AdamOptimizer

np.random.seed(42)

dev = qml.device("default.qubit", wires=1)

num_layers = 3
num_qubits = 1
num_weights_per_layer = 1
total_weights = num_layers * num_qubits * num_weights_per_layer

@qml.qnode(dev)
def circuit(weights, x):
    for layer in range(num_layers):
        qml.RZ(x, wires=0)
        qml.RY(weights[layer], wires=0)
    return qml.expval(qml.PauliZ(0))

def predict(weights, x):
    return circuit(weights, x)

def cost(weights, X, Y):
    preds = np.array([predict(weights, x) for x in X])
    return np.mean((preds - Y) ** 2)

num_points = 40
X = np.linspace(0, 2 * np.pi, num_points)
Y = np.cos(X)

weights = np.random.uniform(-0.1, 0.1, total_weights)

opt = AdamOptimizer(stepsize=0.05)
epochs = 300

for epoch in range(epochs):
    weights = opt.step(lambda w: cost(w, X, Y), weights)
    if (epoch + 1) % 50 == 0:
        c = cost(weights, X, Y)
        print(f"Epoch {epoch + 1:4d} | Loss: {c:.6f}")

final_loss = cost(weights, X, Y)
print(f"Final loss: {final_loss:.6f}")

import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.qasm3 import loads
from qiskit_aer import AerSimulator

qasm_code = """
OPENQASM 3.0;
include "stdgates.inc";

qubit[1] q;
bit[1] c;

// Prepare a superposition (quantum coin flip)
h q[0];

// Mid-circuit measurement
c[0] = measure q[0];

// Active reset: if the outcome is 1, flip back to 0
if (c[0]) {
    x q[0];
}

// Final measurement to verify the state is always 0
bit[1] d;
d[0] = measure q[0];
"""

qc = loads(qasm_code)

sim = AerSimulator()
tqc = transpile(qc, sim, optimization_level=0)
result = sim.run(tqc, shots=4096).result()
counts = result.get_counts()

print("QASM 3 program:")
print(qasm_code)
print("Transpiled circuit:")
print(tqc)
print("Measurement counts:", counts)
print("Active reset verified:", set(counts.keys()).issubset({"0 0", "0"}))

import pennylane as qml
from pennylane import numpy as np

edges = [(0, 1), (0, 3), (1, 2), (1, 4), (2, 3), (3, 4)]
n = 5
p = 2

dev = qml.device("default.qubit", wires=n, shots=None)

def cost_layer(gamma):
    for (u, v) in edges:
        qml.CNOT(wires=[u, v])
        qml.RZ(2 * gamma, wires=v)
        qml.CNOT(wires=[u, v])

def mixer_layer(alpha):
    for w in range(n):
        qml.RX(2 * alpha, wires=w)

@qml.qnode(dev)
def circuit(params):
    gammas, alphas = params
    for w in range(n):
        qml.Hadamard(wires=w)
    for layer in range(p):
        cost_layer(gammas[layer])
        mixer_layer(alphas[layer])
    return qml.probs(wires=range(n))

def cut_value(bitstring):
    s = 1 - 2 * bitstring
    return int(sum(0.5 * (1 - s[u] * s[v]) for (u, v) in edges))

def cost(params):
    probs = circuit(params)
    return -sum(prob * cut_value(np.array([(i >> bit) & 1 for bit in range(n)])) for i, prob in enumerate(probs))

np.random.seed(42)
params = np.random.uniform(0.1, 0.5, size=(2, p), requires_grad=True)

opt = qml.AdamOptimizer(stepsize=0.05)
steps = 300

for _ in range(steps):
    params = opt.step(cost, params)

probs = circuit(params)
best_idx = int(np.argmax(probs))
best_bitstring = np.array([(best_idx >> bit) & 1 for bit in range(n)])
best_cut = cut_value(best_bitstring)

print("Most probable bitstring:", "".join(str(b) for b in best_bitstring[::-1]))
print("Cut value:", best_cut)

import pennylane as qml
from pennylane import numpy as np

np.random.seed(42)

dev = qml.device("default.qubit", wires=1)

num_layers = 6
num_params = num_layers * 2
weights = np.random.uniform(-0.1, 0.1, size=num_params, requires_grad=True)


@qml.qnode(dev)
def circuit(x, w):
    # Data re-uploading: RZ(x) RY(w) repeated for num_layers.
    # x is broadcasted across the batch dimension by PennyLane automatically
    # when passed as a 1-D array.
    for i in range(num_layers):
        qml.RZ(x, wires=0)
        qml.RY(w[i], wires=0)
    return qml.expval(qml.PauliZ(0))


def predict(x, w):
    return circuit(x, w)


def square_loss(targets, predictions):
    predictions = qml.math.stack(predictions)
    return qml.math.mean((targets - predictions) ** 2)


def cost(w, X, Y):
    # Vectorized: pass the whole batch X at once; PennyLane broadcasts the
    # parametric circuit over the batch dimension.
    preds = circuit(X, w)
    return square_loss(Y, preds)


N = 20
X = np.linspace(0.0, 2.0 * np.pi, N, requires_grad=False)
Y = np.cos(X, requires_grad=False)

opt = qml.AdamOptimizer(stepsize=0.1)
batch_size = N  # full-batch gradient descent (vectorized, fast)
epochs = 80

for epoch in range(epochs):
    weights = opt.step(lambda v: cost(v, X, Y), weights)
    if (epoch + 1) % 20 == 0:
        current_loss = cost(weights, X, Y)
        print(f"Epoch {epoch+1:4d} | Loss: {current_loss:.6f}")

final_loss = cost(weights, X, Y)
print(f"Final loss: {final_loss:.6f}")

import pennylane as qml
from pennylane import numpy as np

dev = qml.device("default.qubit", wires=2)

@qml.qnode(dev)
def controlled_phase_circuit(phi):
    qml.PauliX(wires=0)
    qml.PauliX(wires=1)
    qml.ControlledPhaseShift(phi, wires=[0, 1])
    return qml.expval(qml.PauliZ(0))

def main():
    phi = np.pi / 4
    result = controlled_phase_circuit(phi)
    print(result)

if __name__ == "__main__":
    main()

from pytket import Circuit
from pytket.transform import Transform
from pytket.passes import FullPeepholeOptimise, RebaseTket
from pytket.circuit import OpType

def build_circuit():
    c = Circuit(6)
    for layer in range(5):
        for q in range(6):
            c.H(q)
        for q in range(5):
            c.CX(q, q + 1)
        for q in range(6):
            c.Rz(0.1 * (layer + 1), q)
    return c

def gate_counts(circ):
    counts = {}
    for cmd in circ.get_commands():
        op = cmd.op.get_name()
        counts[op] = counts.get(op, 0) + 1
    return counts

def main():
    c = build_circuit()
    before = gate_counts(c)

    FullPeepholeOptimise().apply(c)
    RebaseTket().apply(c)

    after = gate_counts(c)

    print("=== Gate counts before optimization ===")
    for op, count in sorted(before.items()):
        print(f"{op}: {count}")
    print(f"Total: {sum(before.values())}")

    print("\n=== Gate counts after optimization ===")
    for op, count in sorted(after.items()):
        print(f"{op}: {count}")
    print(f"Total: {sum(after.values())}")

if __name__ == "__main__":
    main()
